mapper.select:
select ml.id, ml.stock_date, ml.mix_area, ml.glue, ml.stock_num, s.SAFE_STOCK, ml.remark, ml.del_flag, ml.create_by, ml.create_time, ml.update_by, ml.update_time, ml.bar_code, ml.valid_time, ml.stock_weight from t_ml_glue_stock ml left join t_glue_safe_stock s on ml.mix_area=s.mix_area and ml.glue=s.glue and s.del_flag = '0' where ml.del_flag = '0' and ml.stock_date = #{stockDate} and ml.mix_area = #{mixArea} and INSTR(ml.glue, #{glue}) > 0
order by ml.stock_date desc,valid_time asc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{data.stockDate,jdbcType=TIMESTAMP} STOCK_DATE,#{data.mixArea,jdbcType=VARCHAR} MiX_AREA, #{data.glue,jdbcType=VARCHAR} GLUE
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_ml_glue_stock m inner join temp_table t on m.STOCK_DATE = t.STOCK_DATE and m.MIX_AREA = t.MIX_AREA and m.GLUE = t.GLUE and m.del_flag ='0'

mapper.insert:
insert into t_ml_glue_stock (id,stock_date,mix_area,glue,stock_num,remark,del_flag,create_by,create_time,update_by,update_time,bar_code,valid_time,stock_weight) select NULL id, x.* from (
select #{mlGlueStock.stockDate,jdbcType=TIMESTAMP} stock_date, #{mlGlueStock.mixArea,jdbcType= VARCHAR} mix_area, #{mlGlueStock.glue,jdbcType= VARCHAR} glue, #{mlGlueStock.stockNum,jdbcType=DOUBLE} stock_num, #{mlGlueStock.remark,jdbcType= VARCHAR} remark, #{mlGlueStock.delFlag,jdbcType= VARCHAR} del_flag, #{mlGlueStock.createBy,jdbcType= VARCHAR} create_by, #{mlGlueStock.createTime,jdbcType=TIMESTAMP} create_time, #{mlGlueStock.updateBy,jdbcType= VARCHAR} update_by, #{mlGlueStock.updateTime,jdbcType=TIMESTAMP} update_time, #{mlGlueStock.barCode,jdbcType= VARCHAR} bar_code, #{mlGlueStock.validTime,jdbcType=TIMESTAMP} valid_time, #{mlGlueStock.stockWeight,jdbcType=DOUBLE} stock_weight
) x
